1	//! Bounded append-only event log with `Notify`-based replay and live subscription.
2	//!
3	//! [`EventLog`] is the backbone shared by every HTTP transport (one-shot, SSE, WebSocket).
4	//! Events are stored in a bounded ring (via [`VecDeque`](std::collections::VecDeque)); once the
5	//! ring is full the oldest events are evicted from the head. Subscribers receive a seamless
6	//! replay-then-live stream that ends automatically when a terminal event is yielded.
7	
8	use futures_util::Stream;
9	use paigasus_helikon_core::AgentEvent;
10	use std::{
11	    collections::VecDeque,
12	    sync::{Arc, Mutex},
13	};
14	use tokio::sync::Notify;
15	
16	/// Returns `true` for events that signal end-of-run.
17	///
18	/// Only [`AgentEvent::RunCompleted`] and [`AgentEvent::RunFailed`] are terminal;
19	/// all other variants are non-terminal.
20	fn is_terminal(ev: &AgentEvent) -> bool {
21	    matches!(
22	        ev,
23	        AgentEvent::RunCompleted { .. } | AgentEvent::RunFailed { .. }
24	    )
25	}
26	
27	/// Mutable state inside [`EventLog`], protected by a [`Mutex`].
28	struct EventLogInner {
29	    /// Retained events. May be shorter than total appended events due to ring eviction.
30	    events: VecDeque<AgentEvent>,
31	    /// Sequence number of the first retained event. Increases monotonically as events are evicted.
32	    first_seq: u64,
33	    /// Set to `true` once a terminal event has been appended or [`EventLog::mark_terminal`] is called.
34	    terminal: bool,
35	}
36	
37	/// Bounded append-only event log with `Notify`-based wakeups.
38	///
39	/// Wrapped in an [`Arc`] and shared across all subscribers and transport handlers.
40	/// Appends to a bounded ring; once the ring is full the oldest event is evicted and
41	/// `first_seq` is incremented. Each append wakes all live subscribers via
42	/// [`tokio::sync::Notify`].
43	pub(crate) struct EventLog {
44	    inner: Mutex<EventLogInner>,
45	    notify: Notify,
46	    max_events: usize,
47	}
48	
49	/// Snapshot slice returned by [`EventLog::read_from`].
50	pub(crate) struct ReadSlice {
51	    /// Sequence number of the first retained event in the log.
52	    ///
53	    /// If the requested cursor was evicted by ring truncation, this will be greater than
54	    /// the cursor the caller passed; the returned events start at `first_seq`.
55	    pub first_seq: u64,
56	    /// Events from `max(cursor, first_seq)` up to the current tail (exclusive).
57	    pub events: Vec<AgentEvent>,
58	    /// The sequence number the caller should pass on the next [`EventLog::read_from`] call.
59	    // Consumed by the WebSocket cursor-resume transport added in a later task; the
60	    // replay-then-tail `subscribe` path computes its own cursor and does not read it.
61	    #[allow(dead_code)]
62	    pub next_cursor: u64,
63	    /// `true` once the run has ended (a terminal event was appended or `mark_terminal` called).
64	    pub terminal: bool,
65	}
66	
67	impl EventLog {
68	    /// Create a new log that retains at most `max_events` events.
69	    ///
70	    /// When the log is full, the oldest event is evicted before each new append.
71	    ///
72	    /// # Panics
73	    ///
74	    /// Panics if `max_events` is zero: a zero-capacity ring would evict every
75	    /// event — including the terminal one — leaving subscribers waiting forever.
76	    pub fn new(max_events: usize) -> Self {
77	        assert!(max_events > 0, "max_events must be > 0");
78	        Self {
79	            inner: Mutex::new(EventLogInner {
80	                events: VecDeque::with_capacity(max_events.min(64)),
81	                first_seq: 0,
82	                terminal: false,
83	            }),
84	            notify: Notify::new(),
85	            max_events,
86	        }
87	    }
88	
89	    /// Append an event to the log.
90	    ///
91	    /// If the ring is full, the oldest event is evicted and `first_seq` is incremented.
92	    /// Automatically sets the terminal flag when `ev` is `RunCompleted` or `RunFailed`.
93	    /// Always wakes all live subscribers via [`Notify::notify_waiters`] after appending.
94	    pub fn append(&self, ev: AgentEvent) {
95	        let terminal = is_terminal(&ev);
96	        let mut inner = self.inner.lock().expect("EventLog mutex poisoned");
97	        inner.events.push_back(ev);
98	        while inner.events.len() > self.max_events {
99	            inner.events.pop_front();
100	            inner.first_seq += 1;
101	        }
102	        if terminal {
103	            inner.terminal = true;
104	        }
105	        drop(inner);
106	        self.notify.notify_waiters();
107	    }
108	
109	    /// Mark the log as terminal without appending an event.
110	    ///
111	    /// Used by the start-error path when no run events were ever emitted.
112	    /// Wakes all live subscribers so they can observe the terminal state and finish.
113	    pub fn mark_terminal(&self) {
114	        let mut inner = self.inner.lock().expect("EventLog mutex poisoned");
115	        inner.terminal = true;
116	        drop(inner);
117	        self.notify.notify_waiters();
118	    }
119	
120	    /// Return a slice of retained events starting at `cursor`.
121	    ///
122	    /// If `cursor` is less than `first_seq` (the cursor was evicted by ring truncation),
123	    /// the slice starts at `first_seq` instead. Callers can detect this via `slice.first_seq`.
124	    pub fn read_from(&self, cursor: u64) -> ReadSlice {
125	        let inner = self.inner.lock().expect("EventLog mutex poisoned");
126	        let first_seq = inner.first_seq;
127	        let terminal = inner.terminal;
128	
129	        // Clamp cursor up to first_seq: an under-range cursor starts at the earliest retained event.
130	        let effective_cursor = cursor.max(first_seq);
131	        // How many events to skip from the front of the deque.
132	        let skip = (effective_cursor - first_seq) as usize;
133	        let events: Vec<AgentEvent> = inner.events.iter().skip(skip).cloned().collect();
134	        let next_cursor = effective_cursor + events.len() as u64;
135	
136	        ReadSlice {
137	            first_seq,
138	            events,
139	            next_cursor,
140	            terminal,
141	        }
142	    }
143	
144	    /// Subscribe to this log, returning a stream of events.
145	    ///
146	    /// The stream first replays all retained events from `from` (clamped to `first_seq` if
147	    /// evicted), then delivers new events in real time. The stream ends after the first terminal
148	    /// event is yielded; if the log is already terminal at subscription time, only the retained
149	    /// events are delivered before the stream closes.
150	    ///
151	    /// The returned stream is `Unpin` (wrapped in `Pin<Box<…>>`) so callers can drive it with
152	    /// `stream.next().await` without additional pinning.
153	    ///
154	    /// # Lost-wakeup avoidance
155	    ///
156	    /// Each iteration creates a [`Notify::notified`] future, pins it on the stack, and calls
157	    /// [`.enable()`] *before* calling `read_from`. This guarantees that any
158	    /// [`Notify::notify_waiters`] fired between `read_from` returning an empty slice and the
159	    /// subsequent `.await` is not lost: merely constructing `notified()` without `enable()` does
160	    /// **not** register the waiter.
161	    ///
162	    /// # Pinning rationale
163	    ///
164	    /// The async block is `!Unpin` because its state machine stores a `Notified<'_>` value that
165	    /// borrows `log.notify` (which is also in the state), creating an apparent self-reference.
166	    /// Wrapping the `Unfold` stream in [`Box::pin`] pins the state machine on the heap, making
167	    /// the returned `Pin<Box<…>>` `Unpin` — callers need not pin it themselves.
168	    ///
169	    /// [`Notify::notified`]: tokio::sync::Notify::notified
170	    /// [`.enable()`]: tokio::sync::futures::Notified::enable
171	    pub fn subscribe(self: &Arc<Self>, from: u64) -> impl Stream<Item = AgentEvent> + Send + Unpin {
172	        let log = Arc::clone(self);
173	
174	        // The unfold state carries only the cursor and the done-flag. `log` is captured by
175	        // the closure and cloned fresh for each iteration's async block, so that the async
176	        // block OWNS its Arc<EventLog> and can borrow `log.notify` for the `notified()` future
177	        // without the state tuple also owning `log` (which would require moving it in the return
178	        // statement while it is still borrowed).
179	        Box::pin(futures_util::stream::unfold(
180	            (from, false),
181	            move |(cursor, done)| {
182	                let log = Arc::clone(&log);
183	                async move {
184	                    if done {
185	                        return None;
186	                    }
187	                    loop {
188	                        // Step 1: Register the wakeup future BEFORE reading (lost-wakeup
189	                        // avoidance). `notified()` + `enable()` must precede `read_from` so that
190	                        // any `notify_waiters()` fired between them and the await is not missed.
191	                        let notif = log.notify.notified();
192	                        tokio::pin!(notif);
193	                        notif.as_mut().enable();
194	
195	                        // Step 2: Try to drain one event at the current cursor.
196	                        let slice = log.read_from(cursor);
197	                        // Capture first_seq before consuming slice.events via into_iter().
198	                        let first_seq = slice.first_seq;
199	
200	                        if let Some(ev) = slice.events.into_iter().next() {
201	                            // Fast path: event available. `log` drops when this async block
202	                            // exits; `notif` (which borrows `log.notify`) drops before `log`
203	                            // (LIFO) — no borrow conflict.
204	                            //
205	                            // Advance past any eviction gap in one step: if the ring evicted
206	                            // events past `cursor`, `first_seq` > `cursor` and the naïve
207	                            // `cursor + 1` would still be below `first_seq`, causing the same
208	                            // event to be re-emitted until the cursor walked up to `first_seq`.
209	                            let next_cursor = cursor.max(first_seq) + 1;
210	                            let terminal = is_terminal(&ev);
211	                            return Some((ev, (next_cursor, terminal)));
212	                        }
213	
214	                        // No events available yet.
215	                        if slice.terminal {
216	                            // Terminal with an empty slice: the run ended before we could observe
217	                            // it (all events evicted past our cursor, or mark_terminal with no
218	                            // events).
219	                            return None;
220	                        }
221	
222	                        // Step 3: Await the pre-registered wakeup, then loop to re-check.
223	                        notif.await;
224	                    }
225	                }
226	            },
227	        ))
228	    }
229	}
