/// Unfold state for [`EventLog::subscribe`]: the resume cursor, a once-cloned
/// batch buffer drained in order, and the terminal flag.
struct SubscribeState {
    cursor: u64,
    pending: std::vec::IntoIter<AgentEvent>,
    done: bool,
}
